// Filter token baru yang lolos kriteria
const pairs = $json.pairs || [];
const now = Date.now();

const hasil = [];
for (const p of pairs) {
  if (p.chainId !== 'solana') continue;

  const liq = parseFloat(p.liquidity?.usd || 0);
  const vol = parseFloat(p.volume?.h24 || 0);
  const mcap = parseFloat(p.marketCap || p.fdv || 0);
  const created = p.pairCreatedAt || 0;
  const umurJam = created ? (now - created) / 3600000 : 9999;

  // KRITERIA — edit sesuai selera
  const lolos =
    liq >= 20000 &&          // likuiditas min $20k
    vol >= 10000 &&          // volume 24j min $10k
    mcap > 0 && mcap < 2000000 &&  // mcap di bawah $2jt
    umurJam >= 24 &&         // umur min 24 jam (bukan fresh launch)
    umurJam <= 720;          // umur max 30 hari

  if (lolos) {
    hasil.push({
      json: {
        simbol: p.baseToken?.symbol || '?',
        nama: p.baseToken?.name || '?',
        mint: p.baseToken?.mint || '',
        dex: p.dexId,
        harga: p.priceUsd,
        liq, vol, mcap,
        umur_jam: Math.round(umurJam),
        chg_24h: p.priceChange?.h24,
        url: p.url
      }
    });
  }
}

return hasil;

